preset.warp:
uniform sampler2D sampler_cover;
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's average colour at full brightness, for the gas giants'
// clouds; a grey cover gives way to warm sand, as a gas giant's own.
vec3 coverTone() {
  vec3 c = textureLod(sampler_cover, vec2(0.5), 10.0).rgb;
  float top = max(max(c.r, c.g), c.b);
  float saturation = top - min(min(c.r, c.g), c.b);
  vec3 tone = top > 0.01 ? c / top * 0.85 : vec3(0.0);
  return mix(vec3(0.85, 0.72, 0.55), tone, smoothstep(0.05, 0.25, saturation));
}
float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx);
}
float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
    mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x), f.y),
    f.z);
}
float fbm(vec3 p, int octaves) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    sum += amp * noise3(p);
    p = p * 2.03 + 17.1;
    amp *= 0.5;
  }
  return sum;
}
// A star's colour at `kelvin`, brightest channel 1.
vec3 blackbody(float kelvin) {
  float t = kelvin / 100.0;
  float r = t <= 66.0 ? 1.0 : clamp(1.292936 * pow(t - 60.0, -0.1332047592), 0.0, 1.0);
  float g = t <= 66.0
    ? clamp(0.39008157 * log(t) - 0.63184144, 0.0, 1.0)
    : clamp(1.129890861 * pow(t - 60.0, -0.0755148492), 0.0, 1.0);
  float b = t >= 66.0 ? 1.0 : (t <= 19.0 ? 0.0 : clamp(0.54320679 * log(t - 10.0) - 1.19625409, 0.0, 1.0));
  vec3 c = vec3(r, g, b);
  c /= max(max(c.r, c.g), c.b);
  // A touch more colour than the physics: a sun-like star is white to the
  // eye, but should read as yellow on a screen beside a blue one.
  float grey = dot(c, vec3(0.3, 0.5, 0.2));
  return clamp(mix(vec3(grey), c, 1.5), 0.0, 1.0);
}
// The galaxy's frame on the sky: its pole, and the way to its centre.
const vec3 GALAXY_POLE = vec3(0.2357, 0.9428, -0.2357);
const vec3 GALAXY_CENTRE = vec3(0.8562, -0.0867, 0.5094);
// Ridges where noise crosses its middle: thin, branching lanes.
float ridged(vec3 p, int octaves) {
  return 1.0 - abs(2.0 * fbm(p, octaves) - 1.0);
}
// The galaxy's disc, seen from inside it, as a long exposure shows it: a
// thin band of unresolved stars, swelling into a warm bulge at the centre,
// split along its middle by a dark rift and laced with dust that reddens
// what it does not hide, and pink hydrogen glowing where stars are born.
vec3 milkyWay(vec3 d) {
  float lat = dot(d, GALAXY_POLE);
  if (abs(lat) > 0.6) return vec3(0.0);
  float lon = atan(dot(d, cross(GALAXY_POLE, GALAXY_CENTRE)), dot(d, GALAXY_CENTRE));
  float centre = exp(-lon * lon * 0.7);
  // Thicker towards the centre, and falling off sharply from the plane.
  float height = 0.045 + 0.07 * centre;
  float disc = exp(-abs(lat) / height) * (0.45 + 0.55 * centre);
  float bulge = exp(-(lon * lon / 0.07 + lat * lat / 0.018));
  // Star clouds on three scales, and the grain of single faint stars.
  float clouds = fbm(d * 4.0, 4);
  float detail = fbm(d * 17.0 + 3.0, 4);
  float fine = fbm(d * 45.0 + 5.0, 3);
  float grain = noise3(d * 140.0);
  float light = disc * (0.2 + 1.5 * clouds * clouds) * (0.45 + 1.1 * detail) * (0.6 + 0.8 * fine) * (0.7 + 0.6 * grain);
  vec3 col = mix(vec3(0.78, 0.86, 1.0), vec3(1.0, 0.95, 0.88), 0.3 + 0.7 * centre) * light * 0.6;
  col += vec3(1.0, 0.9, 0.74) * bulge * (0.5 + 0.8 * detail) * (0.8 + 0.4 * fine) * 0.95;
  // Dust: the rift wandering along the plane, filaments off it, and
  // patches everywhere in the band. Hydrogen, deep pink, along the plane
  // where the dust thins; now and then a cloud in the accent. All of it
  // close to the plane, so away from it none of it is worked out.
  if (abs(lat) < 0.3) {
    float wander = 0.012 * sin(lon * 2.3 + 1.0) + 0.008 * sin(lon * 5.1 + 2.0);
    float rift = exp(-pow((lat - wander) / (0.012 + 0.02 * centre), 2.0));
    float patchy = smoothstep(0.35, 0.7, fbm(d * 5.0 + 7.0, 4));
    float lanes = pow(ridged(d * 11.0 + 2.0, 4), 5.0) * exp(-lat * lat / 0.006);
    float specks = smoothstep(0.5, 0.75, fbm(d * 26.0 + 9.0, 3)) * exp(-lat * lat / 0.01);
    float tau = 3.0 * rift * (0.3 + 0.9 * patchy) + 1.6 * lanes + 0.8 * specks + 0.5 * patchy * disc;
    col *= exp(-tau * vec3(0.8, 0.9, 1.0));
    float hii = smoothstep(0.56, 0.82, fbm(d * 6.0 + 13.0, 4)) * exp(-lat * lat / 0.004);
    float other = smoothstep(0.66, 0.88, fbm(d * 5.0 + 41.0, 3)) * exp(-lat * lat / 0.012);
    if (hii + other > 0.001) {
      float wisps = 0.4 + 0.8 * ridged(d * 20.0 + 3.0, 3);
      col += vec3(1.0, 0.25, 0.38) * hii * wisps * 0.22 * exp(-tau * 0.4);
      col += accent() * other * wisps * 0.05;
    }
  }
  return col;
}
// The nearest galaxies beyond our own: a large spiral seen at a slant,
// and two small irregular clouds.
vec3 neighbours(vec3 d) {
  vec3 col = vec3(0.0);
  vec3 at = normalize(vec3(-0.55, 0.35, -0.76));
  float off = length(cross(d, at));
  if (dot(d, at) > 0.0 && off < 0.2) {
    vec3 e1 = normalize(cross(at, vec3(0.2, 1.0, 0.1)));
    vec3 e2 = cross(at, e1);
    vec2 p = vec2(dot(d, e1), dot(d, e2));
    p = vec2(p.x * 0.8 + p.y * 0.6, -p.x * 0.6 + p.y * 0.8);
    float r = length(vec2(p.x, p.y * 3.2));
    float arms = 0.7 + 0.3 * sin(atan(p.y * 3.2, p.x) * 2.0 - log(r + 1e-4) * 5.0);
    col += vec3(1.0, 0.88, 0.72) * (exp(-r / 0.006) * 0.6 + exp(-r / 0.02) * 0.12);
    col += vec3(0.8, 0.84, 1.0) * exp(-r / 0.055) * arms * 0.1;
    col *= 1.0 - 0.7 * smoothstep(0.5, 0.7, fbm(vec3(p * 60.0, 3.0), 4)) * smoothstep(0.01, 0.045, r);
  }
  for (int i = 0; i < 2; i++) {
    vec3 c = normalize(i == 0 ? vec3(0.3, -0.85, 0.42) : vec3(0.42, -0.8, 0.3));
    float size = i == 0 ? 0.09 : 0.045;
    float o = length(cross(d, c)) / size;
    if (dot(d, c) > 0.0 && o < 1.6) {
      float shape = fbm(d * 18.0 + float(i) * 9.0, 4);
      float body = smoothstep(1.1, 0.1, o + (shape - 0.5) * 1.4) * (0.4 + 1.2 * fbm(d * 70.0 + float(i) * 4.0, 3));
      col += vec3(0.82, 0.86, 1.0) * body * 0.13;
      col += vec3(1.0, 0.25, 0.38) * smoothstep(0.62, 0.8, fbm(d * 60.0 + 5.0, 3)) * body * 0.25;
    }
  }
  return col;
}
// Stars too far to move, five layers of cells on the sky: few bright ones,
// ever more faint ones, and many more of those in the band. `pix` is a
// pixel's angle; every star is at least that wide, so none flickers in and
// out between pixels.
vec3 farStars(vec3 d, float pix) {
  float lat = dot(d, GALAXY_POLE);
  float lon = atan(dot(d, cross(GALAXY_POLE, GALAXY_CENTRE)), dot(d, GALAXY_CENTRE));
  float inBand = exp(-lat * lat / 0.012) * (0.4 + 0.6 * exp(-lon * lon));
  vec3 col = vec3(0.0);
  for (int l = 0; l < 5; l++) {
    float fl = float(l);
    float scale = 45.0 * pow(2.0, fl);
    vec3 cell = floor(d * scale);
    vec3 h = hash33(cell + fl * 31.7);
    float chance = (0.07 + 0.07 * fl) * (1.0 + inBand * (0.3 + 0.9 * fl));
    if (h.x > chance) continue;
    vec3 at = normalize(cell + 0.2 + 0.6 * hash33(cell + 5.1 + fl));
    float a = length(cross(d, at));
    // Each layer a magnitude fainter than the one before, give or take.
    float lum = 1.6 * pow(0.4, fl) * (0.2 + 1.8 * pow(h.y, 6.0));
    float size = pix * (0.7 + 0.35 * min(lum, 2.0));
    float twinkle = 1.0 + 0.3 * min(q22, 1.5) * sin(q17 * 40.0 + h.z * 60.0);
    vec3 tint = mix(vec3(1.0), blackbody(3200.0 + 9500.0 * pow(h.z, 1.6)), 0.65);
    col += tint * lum * twinkle * exp(-a * a / (size * size));
  }
  return col;
}
// The point of the segment a..b nearest the ray, its distance from the
// ray, and how far along the ray (t).
float rayToSegment(vec3 rd, vec3 a, vec3 b, out float t) {
  vec3 ba = b - a;
  vec3 oa = -a;
  float baba = dot(ba, ba);
  float rdba = dot(rd, ba);
  float denom = baba - rdba * rdba;
  float u = denom > 1e-6 ? clamp((dot(oa, ba) - rdba * dot(oa, rd)) / denom, 0.0, 1.0) : 0.0;
  vec3 p = a + ba * u;
  t = dot(p, rd);
  return length(p - rd * t);
}
// Stars close enough to fly past: one per cell of a grid in space, found
// by walking the cells along the ray. Each is drawn as the line it moves
// along during a frame or so, so at speed it streaks.
vec3 nearStars(vec3 rd, float pix) {
  const float GRID = 8.0;
  vec3 ro = vec3(0.0, 0.0, q18);
  vec3 p = ro / GRID;
  vec3 cell = floor(p);
  vec3 dirs = sign(rd);
  vec3 safe = vec3(abs(rd.x) < 1e-5 ? 1e-5 : rd.x, abs(rd.y) < 1e-5 ? 1e-5 : rd.y, abs(rd.z) < 1e-5 ? 1e-5 : rd.z);
  vec3 tDelta = abs(1.0 / safe);
  vec3 tMax = (cell + max(dirs, 0.0) - p) / safe;
  vec3 sweep = vec3(0.0, 0.0, -q19 * 5.0 - q24 * q24 * 30.0);
  vec3 col = vec3(0.0);
  for (int i = 0; i < 20; i++) {
    // The grid repeats every 1024 cells along the way, as the odometer
    // q18 does, so its wrapping moves nothing.
    vec3 key = vec3(cell.xy, mod(cell.z, 1024.0));
    vec3 h = hash33(key + 0.5);
    if (h.x < 0.3) {
      vec3 at = (cell + 0.2 + 0.6 * hash33(key + 7.3)) * GRID - ro;
      float t;
      float dist = rayToSegment(rd, at, at + sweep, t);
      if (t > 0.5) {
        float a = dist / t;
        float size = pix * 1.1;
        float streak = length(cross(rd, sweep)) / (t * pix);
        float lum = (0.3 + 2.5 * h.y * h.y * h.y) * 60.0 / (t * t + 40.0) * (1.0 + 3.0 * q24);
        col += blackbody(3000.0 + 12000.0 * h.z * h.z) * lum * exp(-a * a / (size * size)) / (1.0 + 0.5 * streak * (1.0 - 0.8 * q24));
      }
    }
    if (tMax.x < tMax.y) {
      if (tMax.x < tMax.z) { cell.x += dirs.x; tMax.x += tDelta.x; }
      else { cell.z += dirs.z; tMax.z += tDelta.z; }
    } else {
      if (tMax.y < tMax.z) { cell.y += dirs.y; tMax.y += tDelta.y; }
      else { cell.z += dirs.z; tMax.z += tDelta.z; }
    }
  }
  return col;
}
// One octave of ringlets `freq` per radius, faded out where a pixel
// (`fw` wide) spans several of them.
float ringlets(float r, float freq, float seed, float fw) {
  return mix(0.5, noise3(vec3(r * freq, seed, 0.0)), clamp(1.5 - fw * freq * 2.0, 0.0, 1.0));
}
// How much of the light the rings stop at `rel` (in the giant's radii
// from its centre, in the rings' plane). Ringlets on four scales and a
// few gaps; up close, clumps drawn out along the orbit, and closer still
// the single chunks of ice.
float ringDensity(vec3 rel, vec3 axis, float fw) {
  float r = length(rel);
  if (r < 1.35 || r > 2.45) return 0.0;
  float x = (r - 1.35) / 1.1;
  // Saturn's layout, loosely: a faint inner ring, a broad dense one, a
  // wide gap, an outer ring with a narrow gap of its own near its edge.
  float shift = 0.06 * (hash13(vec3(q9, 2.0, 2.0)) - 0.5);
  float profile = mix(0.22, 0.95, smoothstep(0.2, 0.28, x + shift));
  profile = mix(profile, 0.6, smoothstep(0.6, 0.64, x + shift));
  float d = profile
    * (0.55 + 0.45 * ringlets(r, 9.0, q9 + 3.0, fw))
    * (0.5 + 0.5 * ringlets(r, 40.0, q9, fw))
    * (0.6 + 0.4 * ringlets(r, 170.0, q9 + 5.0, fw))
    * (0.75 + 0.25 * ringlets(r, 700.0, q9 + 9.0, fw));
  // The outer edge frays out rather than ending in a line, which is
  // what it would be from just beside it.
  d *= smoothstep(0.0, 0.04, x) * smoothstep(1.0, 0.9, x + (noise3(rel * 6.0 + q9) - 0.5) * 0.05);
  d *= 1.0 - 0.95 * exp(-pow((x + shift - 0.61) / 0.022, 2.0));
  d *= 1.0 - 0.85 * exp(-pow((x - 0.86 - 0.04 * hash13(vec3(q9, 4.0, 4.0))) / 0.005, 2.0));
  d *= 1.0 - 0.6 * exp(-pow((x - 0.15 - 0.05 * hash13(vec3(q9, 3.0, 3.0))) / 0.008, 2.0));
  vec3 e1 = normalize(cross(axis, vec3(0.31, 0.17, 1.0)));
  vec3 e2 = cross(axis, e1);
  vec2 flat2 = vec2(dot(rel, e1), dot(rel, e2));
  vec2 dir = flat2 / r;
  // Clumps: fine across the orbit, long along it.
  vec3 clumpAt = vec3(r * 300.0, dir * r * 30.0);
  float clumps = mix(1.0, 0.45 + 1.1 * noise3(clumpAt + q9), clamp(1.5 - fw * 300.0 * 2.0, 0.0, 1.0));
  float chunks = mix(1.0, 0.2 + 1.6 * noise3(vec3(flat2 * 2500.0, q9)), clamp(1.5 - fw * 2500.0 * 2.0, 0.0, 1.0));
  return clamp(d * clumps * chunks, 0.0, 1.0);
}
// How far a straight ray past a mass at `b` (in horizons) turns between
// signed distances s0 and s1 from its closest point: 2/b over the whole
// line, the weak-field bending.
float weakBend(float b, float s0, float s1) {
  return (s1 / sqrt(s1 * s1 + b * b) - s0 / sqrt(s0 * s0 + b * b)) / b;
}
// The accretion disc of a black hole, in units of its horizon: from the
// innermost stable orbit (3) out to 24, thicker the further out, its gas
// sheared into streaks by the inner orbits going round faster. Its
// density at p, `r` the distance from the axis and `z` the height over the
// middle plane, and how hot it burns there against the average. `fw` is
// how wide a pixel is there, against the disc's surface.
vec2 discGas(vec3 p, float r, float z, vec3 e1, vec3 e2, int detail, float fw) {
  float H = 0.05 + 0.022 * r;
  float radial = smoothstep(2.6, 3.2, r) * smoothstep(24.0, 13.0, r);
  float vertical = exp(-z * z / (H * H));
  if (radial * vertical < 0.01) return vec2(0.0);
  float phi = atan(dot(p, e2), dot(p, e1)) + q17 * 6.0 / pow(r, 1.5);
  float lr = log(r);
  // Round the orbit the pattern repeats, so it is laid on a circle.
  vec3 at = vec3(lr * 14.0, cos(phi + lr * 2.0) * 3.0, sin(phi + lr * 2.0) * 3.0);
  float swirl = fbm(at + vec3(0.0, 0.0, z / H * 0.6) + noise3(at * 1.9 + 4.0) * 1.2, 3);
  // Puffs over the surface, which is what a close pass skims: drawn out
  // along the orbit, as the shear would.
  vec3 near = vec3(r * 3.0, cos(phi) * r * 0.5, sin(phi) * r * 0.5);
  float puffs = fbm(near + z / H * 0.5 + noise3(near * 2.0 + 9.0) * 0.8, detail);
  float dens = radial * vertical * (0.3 + 1.4 * swirl * swirl) * (0.4 + 1.2 * puffs);
  // Fine streaks: thin lanes of gas each on its own orbit, which is what
  // makes the disc read as spinning. Faded out where a lane would be
  // thinner than a pixel, or they would only flicker.
  float lane = noise3(vec3(lr * 45.0, cos(phi) * 1.2, sin(phi) * 1.2) + q9);
  float sharp = clamp(1.5 - fw * 45.0 / r, 0.0, 1.0);
  float streaks = mix(1.0, 0.2 + 3.0 * lane * lane * lane, sharp);
  return vec2(dens * mix(1.0, 0.5 + lane, sharp), (0.35 + 1.3 * swirl * (0.5 + puffs)) * streaks);
}
// Its glow: white-hot inside, deep orange further out, as Interstellar
// showed it - which left out the Doppler shift that would brighten one
// side. Falling off slower than the physics would, so the outer disc still
// glows instead of turning to brown.
vec3 discGlow(float r) {
  float x = clamp((r - 2.6) / 21.4, 0.0, 1.0);
  vec3 hot = mix(vec3(1.0, 0.85, 0.6), vec3(1.0, 0.36, 0.06), pow(x, 0.4));
  return hot * pow(3.0 / r, 0.9) * sqrt(max(1.0 - 1.0 / r, 0.0));
}
// A black hole (q8 2) at q4..q6, q7 the edge of its disc, if it has one
// (q14): the ray bent around it step by step (photons around a mass, in
// units of the horizon), where it leaves to (`dir`), and the glowing gas
// it passed through on the way - in front and, bent over the top and
// under, behind. Outside the sphere stepped through, the bending is added
// in closed form, so its edge does not show.
void blackHole(vec3 rd, out vec3 dir, out vec3 col, out float alpha) {
  const float NEAR = 40.0;
  vec3 c = vec3(q4, q5, q6);
  float rs = q7 / 24.0;
  dir = rd;
  col = vec3(0.0);
  alpha = 0.0;
  vec3 p = -c / rs;
  vec3 eye = p;
  vec3 v = rd;
  float along = dot(-p, v);
  float b = max(length(p + v * along), 1e-3);
  float r0 = length(p);
  vec3 toward = normalize(-p - v * along);
  // The photon ring: light that came in at just the angle to circle the
  // hole before getting away, so a thin bright line right on the edge of
  // its shadow. Its brightness and width are the music's - the highs keep
  // it shimmering, the beat makes it flare.
  const float GRAZING = 2.598;
  float pixels = max(r0 / texsize.y, 1e-3);
  float width = max(0.04, pixels * 1.5) * (1.0 + 0.8 * q21);
  float ring = exp(-max(b - GRAZING, 0.0) / width) * exp(-max(GRAZING - b, 0.0) / (width * 0.5))
    + 0.08 * exp(-max(b - GRAZING, 0.0) / (max(0.04, pixels * 1.5) * 6.0)) * step(GRAZING, b);
  vec3 rim = vec3(1.0, 0.97, 0.92) * ring * (0.6 + 0.5 * min(q22, 2.0) + 2.0 * q21);
  if (b > NEAR - 6.0 || (along < 0.0 && r0 > NEAR)) {
    dir = normalize(v + toward * weakBend(b, -along, 1e4));
    return;
  }
  float inside = sqrt(max(NEAR * NEAR - b * b, 0.0));
  if (r0 > NEAR) {
    p += v * (along - inside);
    v = normalize(v + toward * weakBend(b, -along, -inside));
  }
  bool hasDisc = q14 > 0.5;
  vec3 axis = normalize(vec3(sin(q15), cos(q15) * cos(q16), cos(q15) * sin(q16)));
  vec3 e1 = normalize(cross(axis, vec3(0.31, 0.17, 1.0)));
  vec3 e2 = cross(axis, e1);
  float h2 = b * b;
  float through = 1.0;
  float travelled = 0.0;
  float jitter = fract(52.9829 * fract(dot(uv_orig * texsize.xy, vec2(0.06711, 0.00584))));
  for (int i = 0; i < 200; i++) {
    float r = length(p);
    if (r < 1.0) {
      col += rim * through;
      alpha = 1.0;
      return;
    }
    if (r > NEAR + 2.0 && dot(p, v) > 0.0) break;
    float dt = clamp(0.12 * (r - 0.9), 0.03, 1.5);
    v += -1.5 * h2 * p / pow(r, 5.0) * dt;
    vec3 pn = p + v * dt;
    if (hasDisc) {
      // The gas along this step, sampled where the step comes near it.
      float s0 = dot(p, axis);
      float s1 = dot(pn, axis);
      float H = 0.05 + 0.022 * r;
      if (s0 * s1 < 0.0 || min(abs(s0), abs(s1)) < 2.2 * H) {
        // Finer where the step is long against the gas's thickness, and
        // the puffs' finest detail only near, where it is bigger than a
        // pixel.
        int n = clamp(int(length(pn - p) / H * 1.5) + 1, 2, 5);
        int detail = travelled < 6.0 ? 4 : travelled < 15.0 ? 3 : 2;
        float ds = length(pn - p) / float(n);
        for (int k = 0; k < 5; k++) {
          if (k >= n) break;
          vec3 q = mix(p, pn, (float(k) + jitter) / float(n));
          float z = dot(q, axis);
          float rr = length(q - axis * z);
          float fw = length(q - eye) / texsize.y / max(abs(dot(normalize(v), axis)), 0.25);
