  surface = mix(surface, bb * 1.4, smoothstep(0.6, 0.95, heat));
  surface = mix(surface, mix(bb, vec3(1.0, 0.96, 0.85), 0.6) * 2.6, smoothstep(0.95, 1.25, heat));
