// `v` turned by `angle` around `axis`.
vec3 turn(vec3 v, vec3 axis, float angle) {
  return v * cos(angle) + cross(axis, v) * sin(angle) + axis * dot(axis, v) * (1.0 - cos(angle));
}
// Land: broad continents with ridged mountain chains in them, 0..1.
float terrain(vec3 p) {
  float broad = fbm(p * 1.6, 5);
  float ridges = 1.0 - abs(2.0 * fbm(p * 4.0 + 7.0, 4) - 1.0);
  return broad + 0.22 * ridges * ridges * smoothstep(0.45, 0.65, broad);
}
// Clouds on the unit sphere at `n`: noise pushed around by noise into
