    eye = normalize(eye - axis * dot(eye, axis) * 0.6);
    float d = length(n - eye);
    float spin = dot(eye, axis) < 0.0 ? -1.0 : 1.0;
    n = turn(n, eye, spin * 2.5 * exp(-d * d / 0.06));
