    ? starBody(rd, c, q7, q10, q9, pix, g1, d1)
    : q8 < 1.5
      ? giantBody(rd, c, q7, normalize(sunAt - c), sun, pix, d1)
      : q8 < 5.5
        ? worldBody(rd, c, q7, normalize(sunAt - c), sun, q8 - 3.0, pix, g1, d1)
        : neutronStar(rd, c, q7, pix, g1, d1);
  if (q8 > 0.5 && q8 < 5.5 && (q8 < 1.5 || q8 > 2.5)) moons(rd, c, q7, sunAt, sun, pix, a, d1);
