  vec3 gFar = g2;
  if (d2 < d1) {
    near = b;
    far = a;
    gNear = g2;
    gFar = g1;
  }
  glow = gNear * (1.0 - 0.85 * near.a) + gFar * (1.0 - near.a) * (1.0 - 0.85 * far.a);
  return vec4(near.rgb + far.rgb * (1.0 - near.a), near.a + far.a * (1.0 - near.a));
}
 shader_body {
  vec2 s = (uv_orig - 0.5) / aspect.yx;
  s.y = -s.y;
  vec3 fwd = vec3(sin(q1) * cos(q2), sin(q2), cos(q1) * cos(q2));
  vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), fwd));
  vec3 up = cross(fwd, right);
  vec3 r2 = cos(q3) * right + sin(q3) * up;
  up = cross(fwd, r2);
  vec3 rd = normalize(fwd * 1.0 + s.x * r2 + s.y * up);
  float pix = 1.0 / texsize.y;
  vec3 look = rd;
  vec3 hole = vec3(0.0);
  float holeA = 0.0;
  if (q8 > 1.5 && q8 < 2.5) {
    blackHole(rd, look, hole, holeA);
    look = normalize(mix(rd, look, q20));
  }
  vec3 sd = vec3(cos(q23) * look.x - sin(q23) * look.z, look.y, sin(q23) * look.x + cos(q23) * look.z);
