preset.comp:
// The texture repeats: a sample past one edge would bring light in from
// the other.
float onScreen(vec2 at) {
  return step(0.0, at.x) * step(at.x, 1.0) * step(0.0, at.y) * step(at.y, 1.0);
}
 shader_body {
  vec3 col = texture(sampler_main, uv).rgb;
  // Light spilling around what is brightest, as in a lens: tight around
  // a star, wide and faint around a sun filling the view. From the
  // blurred copies of the picture, with only their bright part kept.
  vec3 b1 = texture(sampler_blur1, uv).rgb * scale1 + bias1;
  vec3 b2 = texture(sampler_blur2, uv).rgb * scale2 + bias2;
  vec3 b3 = texture(sampler_blur3, uv).rgb * scale3 + bias3;
  vec3 bloom = max(b1 - 0.6, 0.0) * 0.5 + max(b2 - 0.45, 0.0) * 0.5 + max(b3 - 0.3, 0.0) * 0.5;
  // A black hole's disc lights the space around it: a wide warm haze,
  // held back over the shadow, which stays black.
  float holeHaze = step(1.5, q8) * step(q8, 2.5) * q20 * q14;
  holeHaze *= mix(0.3, 1.0, smoothstep(0.0, 0.05, dot(col, vec3(0.3, 0.5, 0.2))));
  bloom += max(b3 - 0.12, 0.0) * vec3(1.0, 0.55, 0.2) * holeHaze;
  // Laid over like light, not paint: it brightens the dark around a
  // star more than the star itself, whose surface stays readable.
  col = 1.0 - (1.0 - col) * (1.0 - min(bloom * (1.0 - q24), 1.0));
  vec3 spikes = vec3(0.0);
  for (int k = 0; k < 4; k++) {
    float a = 0.785 + float(k) * 1.5708 + q3;
    vec2 dir = vec2(cos(a), sin(a)) * vec2(aspect.y, 1.0);
    for (int i = 1; i <= 10; i++) {
      float r = float(i) * 0.012;
      vec2 at = uv + dir * r;
      spikes += max(texture(sampler_main, at).rgb - 0.9, 0.0) * (1.0 - float(i) / 11.0) * onScreen(at);
    }
  }
  col += spikes * 0.25;
  // The jump: the picture pulled out from the middle, bluer ahead, and a
  // flash at its height, which hides the swap to the next system.
  if (q24 > 0.01) {
    vec2 toward = vec2(0.5) - uv;
    vec3 pulled = vec3(0.0);
    for (int i = 0; i < 12; i++) {
      pulled += texture(sampler_main, uv + toward * (float(i) / 12.0) * 0.3 * q24).rgb;
    }
    col = mix(col, pulled / 12.0 * 1.4, q24);
    col *= mix(vec3(1.0), vec3(0.8, 0.92, 1.3), q24 * (1.0 - clamp(rad * 1.4, 0.0, 1.0)));
  }
  col += vec3(0.85, 0.92, 1.0) * q25 * 1.3;
  col *= 1.0 - 0.35 * pow(clamp(rad * 1.2, 0.0, 1.0), 2.5);
  ret = col;
 }
